--
-- Name: v_unified_audit_logs; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_unified_audit_logs AS
 SELECT 'audit_logs'::text AS source_table,
    audit_logs.id AS source_id,
    'SECURITY_SYSTEM'::text AS domain,
    (audit_logs.action)::text AS action,
    (audit_logs.resource_type)::text AS entity_type,
    (audit_logs.resource_id)::text AS entity_id,
    audit_logs.user_id AS actor_user_id,
    COALESCE(audit_logs.details, (audit_logs.severity)::text) AS details,
    'success'::text AS status,
    (audit_logs.ip_address)::text AS ip_address,
    audit_logs.created_at
   FROM public.audit_logs
UNION ALL
 SELECT 'setting_audit_logs'::text AS source_table,
    setting_audit_logs.id AS source_id,
    'SETTINGS'::text AS domain,
    'UPDATE_SETTING'::text AS action,
    (setting_audit_logs.category)::text AS entity_type,
    (setting_audit_logs.setting_key)::text AS entity_id,
    setting_audit_logs.changed_by_id AS actor_user_id,
    COALESCE(setting_audit_logs.reason, 'Setting changed'::text) AS details,
    'success'::text AS status,
    NULL::text AS ip_address,
    setting_audit_logs.created_at
   FROM public.setting_audit_logs
UNION ALL
 SELECT 'communication_logs'::text AS source_table,
    communication_logs.id AS source_id,
    'COMMUNICATION'::text AS domain,
    ('DISPATCH_'::text || upper((communication_logs.channel)::text)) AS action,
    (communication_logs.recipient_type)::text AS entity_type,
    (communication_logs.recipient_id)::text AS entity_id,
    communication_logs.sender_id AS actor_user_id,
    (COALESCE(communication_logs.subject, communication_logs.template_code, 'Direct message'::character varying))::text AS details,
    (communication_logs.status)::text AS status,
    NULL::text AS ip_address,
    communication_logs.created_at
   FROM public.communication_logs
UNION ALL
 SELECT 'codex_audit_logs'::text AS source_table,
    codex_audit_logs.id AS source_id,
    'CODEX_SECURITY'::text AS domain,
    (codex_audit_logs.action)::text AS action,
    (codex_audit_logs.entity_type)::text AS entity_type,
    (codex_audit_logs.entity_id)::text AS entity_id,
    codex_audit_logs.user_id AS actor_user_id,
    codex_audit_logs.details,
    (codex_audit_logs.status)::text AS status,
    (codex_audit_logs.ip_address)::text AS ip_address,
    codex_audit_logs.created_at
   FROM public.codex_audit_logs
UNION ALL
 SELECT 'student_lifecycle_logs'::text AS source_table,
    student_lifecycle_logs.id AS source_id,
    'STUDENT_ACADEMIC'::text AS domain,
    (student_lifecycle_logs.action)::text AS action,
    'STUDENT'::text AS entity_type,
    (student_lifecycle_logs.student_id)::text AS entity_id,
    student_lifecycle_logs.performed_by_id AS actor_user_id,
    (COALESCE(student_lifecycle_logs.reason, (student_lifecycle_logs.notes)::character varying, 'Lifecycle transition'::character varying))::text AS details,
    (student_lifecycle_logs.to_status)::text AS status,
    NULL::text AS ip_address,
    student_lifecycle_logs.created_at
   FROM public.student_lifecycle_logs;


